import {mountFarmContext,openMarketplace,api} from './live-data.js'
let disposeContext=()=>{},disposeMarket=()=>{},activeFarm=''
function dashboardMarkup(){return `<section class="reference-dashboard"><div class="task-pane"><header><button class="back-button">‹</button><div><span class="folder">▰</span><strong>Farm activity</strong></div><button class="more-button">•••</button></header><label class="task-search">⌕ <input id="task-filter" placeholder="Search farm records..."/><button type="button">⚙</button></label><div class="task-group"><div class="group-title"><span>⌄ &nbsp;📌 Farm records</span><small>2</small></div><article data-view="Livestock"><i class="check red"></i><div><strong>Livestock health</strong><p id="livestock-summary">Loading livestock records…</p><span>#Animal-health</span></div><time>Open</time></article><article data-view="Crops"><i class="check amber"></i><div><strong>Growing crops</strong><p id="crop-summary">Loading field records…</p><span>#Crop-protection</span></div><time>Open</time></article></div><div class="task-group"><div class="group-title"><span>⌄ &nbsp; Live information</span><small>3</small></div><article data-view="Settings"><i class="check green"></i><div><strong>Farm settings</strong><p>Update profile and farm coordinates</p><span>#Farm</span></div><time>Open</time></article><article data-home="true"><i class="check blue"></i><div><strong>Market prices</strong><p id="market-summary">Loading market information…</p><span>#Market</span></div><time>Published</time></article><article><i class="check purple"></i><div><strong>Weather outlook</strong><p id="weather-summary">Loading local weather…</p><span>#Planning</span></div><time>Now</time></article></div><button class="collapsed-group" data-view="Alerts">› &nbsp; Alerts <small id="alert-count">0</small></button><button class="collapsed-group" data-view="Reports">› &nbsp; Reports</button><div id="live-weather-detail" class="live-weather-detail" aria-live="polite">Loading farm weather…</div></div><div class="farm-map-pane"><div class="live-farm-map" aria-label="Selected farm location"></div><div class="map-toolbar"><select class="map-layer" aria-label="Map layer"><option value="standard">Standard map</option><option value="satellite">Satellite</option></select><button class="map-recenter">Recenter farm</button><button class="map-live-location" disabled>Use live location</button></div><div class="live-location-panel" hidden><p class="live-location-status" role="status"></p><button class="save-gps-farm" disabled>Save GPS as farm location</button></div><div class="map-weather"><b id="map-temperature">Weather…</b><span id="map-wind">Connecting</span></div></div></section>`}

let navigationInProgress=false
function releaseDashboard(){disposeContext();disposeMarket();activeFarm='';navigationInProgress=true;const workspace=document.querySelector('.app-shell .workspace');workspace?.querySelector('.reference-dashboard')?.remove();workspace?.classList.remove('reference-active');setTimeout(()=>{navigationInProgress=false;sync()},250)}
function openView(label){const button=[...document.querySelectorAll('.app-shell aside nav button')].find(item=>item.textContent.includes(label));releaseDashboard();setTimeout(()=>button?.click(),0)}
async function getApi(path,token){const response=await fetch(`/api/v1${path}`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw new Error(`Request failed (${response.status})`);return response.json()}

async function hydrate(workspace){let session;try{session=JSON.parse(sessionStorage.getItem('agrinexus.session')||'null')}catch{return}const token=session?.accessToken;const farmId=document.querySelector('.farm-switcher select')?.value;if(!token||!farmId)return;
workspace.querySelectorAll('[data-view]').forEach(item=>item.addEventListener('click',()=>openView(item.dataset.view)));workspace.querySelector('[data-home]')?.addEventListener('click',async()=>{const farm=await api(`/farms/${farmId}`,token).catch(()=>({}));disposeMarket=openMarketplace(token,farm.province||'')});const filter=workspace.querySelector('#task-filter');filter?.addEventListener('input',()=>workspace.querySelectorAll('.task-group article').forEach(item=>{item.hidden=!item.textContent.toLowerCase().includes(filter.value.toLowerCase())}));
workspace.querySelector('.back-button')?.addEventListener('click',()=>history.back());workspace.querySelector('.more-button')?.addEventListener('click',()=>workspace.querySelectorAll('.collapsed-group').forEach(item=>item.hidden=!item.hidden));disposeContext=mountFarmContext(workspace,farmId,token);
try{const[dashboard,animals,fields,prices]=await Promise.all([getApi(`/farms/${farmId}/dashboard`,token),getApi(`/farms/${farmId}/animals`,token),getApi(`/farms/${farmId}/fields`,token),getApi('/market-prices',token)]);if(!workspace.isConnected||activeFarm!==farmId)return;workspace.querySelector('#livestock-summary').textContent=`${animals.length} animal record${animals.length===1?'':'s'}`;workspace.querySelector('#crop-summary').textContent=`${fields.length} registered field${fields.length===1?'':'s'}`;workspace.querySelector('#market-summary').textContent=`${prices.length} verified reference prices`;workspace.querySelector('#alert-count').textContent=dashboard.unreadNotifications;}catch(error){if(workspace.isConnected&&activeFarm===farmId)workspace.querySelector('#market-summary').textContent=error.message}}

function sync(){if(navigationInProgress)return;const workspace=document.querySelector('.app-shell .workspace');if(!workspace){disposeContext();disposeMarket();activeFarm='';return}const dashboard=workspace.querySelector('.page-heading h2')?.textContent?.trim()==='Dashboard';workspace.classList.toggle('reference-active',dashboard);const farm=document.querySelector('.farm-switcher select')?.value;if(dashboard&&activeFarm!==farm){disposeContext();disposeMarket();workspace.querySelector('.reference-dashboard')?.remove();activeFarm=farm}if(dashboard&&!workspace.querySelector('.reference-dashboard')){workspace.insertAdjacentHTML('afterbegin',dashboardMarkup());hydrate(workspace)}}document.addEventListener('click',event=>{if(event.target.closest('.app-shell aside nav button'))releaseDashboard();const headerButton=event.target.closest('.app-shell>header button');if(!headerButton)return;if(headerButton.classList.contains('user-menu'))openView('Settings');else if(headerButton.textContent.includes('🔔'))openView('Alerts');else if(headerButton.classList.contains('header-icon'))openView('Livestock')},true);const observer=new MutationObserver(sync);observer.observe(document.body,{childList:true,subtree:true});sync()

document.addEventListener('change',event=>{if(event.target.matches('.farm-switcher select'))setTimeout(sync,0)})
